CREATE TABLE IF NOT EXISTS ai_models(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,base_url VARCHAR(300) NOT NULL,model VARCHAR(160) NOT NULL,kind ENUM('chat','transcription') NOT NULL DEFAULT 'chat',api_key_enc TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,max_tokens INT NOT NULL DEFAULT 4096,timeout_seconds INT NOT NULL DEFAULT 120,test_status VARCHAR(20) NOT NULL DEFAULT 'untested',test_message VARCHAR(300),tested_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_settings(id INT PRIMARY KEY,chat_model_id INT NULL,transcription_model_id INT NULL);
INSERT IGNORE INTO ai_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS ai_calls(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NULL,model_id INT NULL,model VARCHAR(160),purpose VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL,duration_ms INT NOT NULL DEFAULT 0,prompt_tokens INT NOT NULL DEFAULT 0,completion_tokens INT NOT NULL DEFAULT 0,error VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS ai_threads(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,title VARCHAR(100) NOT NULL,conversation_id INT NULL,busy_token VARCHAR(64),busy_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS ai_messages(id INT PRIMARY KEY AUTO_INCREMENT,thread_id INT NOT NULL,role ENUM('user','assistant') NOT NULL,content MEDIUMTEXT NOT NULL,model VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(thread_id) REFERENCES ai_threads(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_report_insights(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,days INT NOT NULL,content MEDIUMTEXT NOT NULL,model VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
